{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 청년 지원에 금융 상담이나 교육이 있는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제14조제1항은 시장이 청년의 경제적 자립과 안정적인 금융생활을 지원하기 위한 대책을 수립·시행하여야 하고, 청년의 금융생활 지원 등을 위한 교육과 상담 지원을 위해 노력하여야 하며, 예산의 범위에서 청년 금융생활 지원 등에 관한 사항을 지원할 수 있다고 정한다. 따라서 서울시 청년 지원에는 금융 상담이나 교육이 포함될 수 있으나, 이는 시장이 노력할 사항이자 예산 범위에서 지원할 수 있는 사항이다.",
          "b_ids": "청년:제14조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
